#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <float.h>
#include <vector>

__global__ void max_reduce_dim_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    long long outer,
    long long reduce,
    long long inner,
    long long total_out)
{
    constexpr int TX = 128;
    constexpr int SPLIT = 4;
    __shared__ float sm[SPLIT][TX];
    const long long tile_inner = (long long)TX;
    const long long tiles_per_outer = (inner + tile_inner - 1) / tile_inner;
    const long long total_tiles = outer * tiles_per_outer;
    const long long step = (long long)gridDim.x;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    for (long long tile = blockIdx.x; tile < total_tiles; tile += step) {
        const long long o = tile / tiles_per_outer;
        const long long it = tile - o * tiles_per_outer;
        const long long i0 = it * tile_inner + tx;
        const long long base = o * reduce * inner;
        const bool v0 = i0 < inner;
        const long long stride = (long long)SPLIT * inner;
        const float* xr = x + base + i0 + (long long)ty * inner;
        const float* xend = x + base + i0 + reduce * inner;
        float m0 = -FLT_MAX;
        if (v0) {
            #pragma unroll 4
            for (const float* p = xr; p < xend; p += stride) {
                m0 = fmaxf(m0, __ldg(p));
            }
        }
        sm[ty][tx] = m0;
        __syncthreads();
        if (ty == 0) {
            const long long out_base = o * inner;
            m0 = fmaxf(fmaxf(sm[0][tx], sm[1][tx]), fmaxf(sm[2][tx], sm[3][tx]));
            if (v0) out[out_base + i0] = m0;
        }
