    const int threads_y = 4;
    const int total_threads = threads_x * threads_y;
    const long long tile_inner = (long long)threads_x;
    long long tiles_per_outer = (inner + tile_inner - 1) / tile_inner;
    long long total_tiles = outer * tiles_per_outer;
    long long blocks_ll = total_tiles;
    const long long wave_blocks = max_reduce_wave_blocks(total_threads);
    if (blocks_ll > wave_blocks) blocks_ll = wave_blocks;
    if (blocks_ll < 1) blocks_ll = 1;
    dim3 blocks((unsigned int)blocks_ll);
    dim3 threads(threads_x, threads_y);

    auto stream = at::cuda::getCurrentCUDAStream();
    max_reduce_dim_kernel<<<blocks, threads, 0, stream>>>(
        y.data_ptr<float>(),
        out.data_ptr<float>(),
        outer,
        reduce,
        inner,
        total_out
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
